index e0291f3e..1cb3dc13 100644
--- a/dmtools-core/src/main/java/com/github/istin/dmtools/file/FileTools.java
+++ b/dmtools-core/src/main/java/com/github/istin/dmtools/file/FileTools.java
@@ -134,6 +134,86 @@ public class FileTools {
         }
