        get: (k) => k == 'JIRA_CLOUD' ? 'true' : null,
      );
      expect(policy.maxAttempts, 7);
    });

    test('forUrl keeps the default policy elsewhere', () {
      final policy = SyncRetryPolicy.forUrl('http://127.0.0.1:1/x');
      expect(policy.maxAttempts, 5);
    });
  });
}

