import 'dart:convert';
import 'dart:io';

import '../../mcp/tool_definition.dart';
import '../../mcp/tool_param.dart';

/// Returns all file MCP tool definitions.
///
/// Tool names and argument schemas mirror the Java `@MCPTool` annotations.
List<ToolDefinition> fileTools() => [
      _readTool(),
      _writeTool(),
      _listTool(),
      _existsTool(),
      _deleteTool(),
      _copyTool(),
      _moveTool(),
      _mkdirTool(),
      _readLinesTool(),
      _writeLinesTool(),
      _appendTool(),
      _infoTool(),
      _readJsonTool(),
      _writeJsonTool(),
      _existsInPathTool(),
      _getSizeTool(),
      _watchTool(),
      _renameTool(),
