        'TESTRAIL_API_KEY': 'key',
        'TESTRAIL_PROJECT': 'p1',
      });

      final jira = IntegrationClients.instance.jira();
      final testrail = IntegrationClients.instance.testrail();

      expect(jira, isA<JiraClient>());
      expect(testrail, isA<TestRailClient>());
