        'JIRA_RETRY_JITTER_FACTOR': '0.1',
      };
      final policy = SyncRetryPolicy.fromEnvMap((k) => env[k]);
      expect(policy.maxAttempts, 3);
      expect(policy.baseDelayMs, 50);
