/// Tool names and argument schemas mirror the Java `@MCPTool` annotations.
List<ToolDefinition> fileTools() => [
      _readTool(),
      _writeTool(),
      _listTool(),
      _existsTool(),
      _deleteTool(),
      _copyTool(),
      _moveTool(),
