+                children.map(c -> c.toAbsolutePath().normalize().toString()).sorted().forEach(entries::put);
+            }
+            return new JSONObject().put("entries", entries).toString();
+        } catch (Exception e) {
+            logger.error("Failed to list directory: {} - {}", dirPath, e.getMessage(), e);
+            return null;
+        }
+    }
