    String method,
    String url, {
    String? headerFile,
    String? bodyFile,
    String? headerDumpFile,
    bool followRedirects = false,
  }) {
    final args = [
      '-s',
      '-X',
      method,
      '-w',
      '\n%{http_code}',
      '--connect-timeout',
      '$connectTimeoutSeconds',
      '--max-time',
      '$maxTimeSeconds',
