/// All operations use `dart:io` directly.
library;

import 'dart:convert';
import 'dart:io';

import '../../mcp/tool_definition.dart';
import '../../mcp/tool_param.dart';

/// Returns all file MCP tool definitions.
///
/// Tool names and argument schemas mirror the Java `@MCPTool` annotations.
List<ToolDefinition> fileTools() => [
      _readTool(),
      _writeTool(),
      _listTool(),
      _existsTool(),
      _deleteTool(),
      _copyTool(),
      _moveTool(),
      _mkdirTool(),
      _readLinesTool(),
      _writeLinesTool(),
      _appendTool(),
      _infoTool(),
      _readJsonTool(),
      _writeJsonTool(),
      _existsInPathTool(),
      _getSizeTool(),
      _watchTool(),
      _renameTool(),
      _searchTool(),
    ];

/// `file_read` — read the contents of a text file.
ToolDefinition _readTool() => ToolDefinition(
      name: 'file_read',
      description: 'Read the contents of a text file',
      integration: 'file',
      category: 'filesystem',
      params: [
        ToolParam(name: 'path', description: 'File path to read'),
      ],
    );

