      expect(policy.statusDelayMs(1), 1000);
      expect(policy.statusDelayMs(2), 2000);
      expect(policy.statusDelayMs(3), 4000);
    });

    test('delay caps at maxDelayMs', () {
      expect(policy.statusDelayMs(4), 6000);
      expect(policy.statusDelayMs(8), 6000);

